import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [goods, setGoods] = useState([]);
  const [search, setSearch] = useState('');
  const [filteredGoods, setFilteredGoods] = useState([]);

  // Fetch goods from backend
  useEffect(() => {
    fetch('http://localhost:5000/api/goods/getallgoods')
      .then(res => res.json())
      .then(data => setGoods(data))
      .catch(err => console.error('Error fetching goods:', err));
  }, []);

  // Filter goods by search
  useEffect(() => {
    setFilteredGoods(
      goods.filter(good =>
        good.name.toLowerCase().includes(search.toLowerCase())
      )
    );
  }, [search, goods]);

  return (
    <div className="amazon-container">
      <nav className="navbar">
        <div className="logo">MyShop</div>
        <input
          type="text"
          className="search-box"
          placeholder="Search for goods..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </nav>
      <main className="goods-list">
        {filteredGoods.length > 0 ? (
          filteredGoods.map(good => (
            <div key={good._id} className="good-item">
              <div className="good-name">{good.name}</div>
              <div className="good-price">${good.price}</div>
              {good.imageUrl && good.imageUrl.length > 0 && (
                <img
                  src={good.imageUrl[0]}
                  alt={good.name}
                  className="good-image"
                  style={{ maxWidth: '100px', marginTop: '8px' }}
                />
              )}
              <div className="good-brand">{good.brand}</div>
              <div className="good-category">{good.category}</div>
            </div>
          ))
        ) : (
          <div className="no-results">No goods found.</div>
        )}
      </main>
    </div>
  );
}

export default App;
